repro:
cat > /usr/local/bin/systemctl <<'EOF'
#!/bin/bash
# Fake systemctl shim for systems where systemd is not PID 1 (containers)
APP=/opt/appmonitor/appmonitor
PIDFILE=/var/run/appmonitor.pid
UNIT_DIR=/etc/systemd/system
WANTS=/etc/systemd/system/multi-user.target.wants
REAL=/usr/bin/systemctl.real

active() { [ -f "$PIDFILE" ] && kill -0 "$(cat "$PIDFILE" 2>/dev/null)" 2>/dev/null; }

args=()
for a in "$@"; do
  case "$a" in
    --*) : ;; -*) : ;; *) args+=("$a") ;;
  esac
done
cmd="${args[0]}"; sub="${args[1]}"; name="${sub%.service}.service"

case "$cmd" in
  is-system-running) echo running; exit 0 ;;
  daemon-reload|daemon-reexec|preset|mask|unmask|reset-failed) exit 0 ;;
  enable)
    for n in "${args[@]:1}"; do u="${n%.service}.service"; [ -e "$UNIT_DIR/$u" ] || continue
      mkdir -p "$WANTS"; ln -sf "$UNIT_DIR/$u" "$WANTS/$u"; echo "Created symlink $WANTS/$u -> $UNIT_DIR/$u."; done; exit 0 ;;
  disable)
    for n in "${args[@]:1}"; do u="${n%.service}.service"; rm -f "$WANTS/$u"; done; exit 0 ;;
  is-enabled) [ -e "$WANTS/$name" ] && { echo enabled; exit 0; } || { echo disabled; exit 1; } ;;
  start)
    active && { echo active; exit 0; }
    while IFS= read -r line; do case "$line" in
      Environment=*) export "${line#Environment=}" ;;
      EnvironmentFile=*) f="${line#EnvironmentFile=}"; f="${f#-}"; f="${f#-}"; [ -f "$f" ] && { set -a; . "$f"; set +a; } ;;
    esac; done < "$UNIT_DIR/$name"
    nohup "$APP" >/dev/null 2>&1 & echo $! > "$PIDFILE"; exit 0 ;;
  stop) active && kill "$(cat $PIDFILE)" 2>/dev/null; rm -f "$PIDFILE"; exit 0 ;;
  restart|try-restart|reload-or-restart) active && kill "$(cat $PIDFILE)" 2>/dev/null; sleep 0.3; exec "$0" start "$name" ;;
  reload) exit 0 ;;
  is-active) if active; then echo active; exit 0; else echo inactive; exit 3; fi ;;
  status) if active; then echo "* $name - AppMonitor daemon"; echo "     Loaded: loaded ($UNIT_DIR/$name; enabled)"; echo "     Active: active (running)"; exit 0; else echo "* $name - AppMonitor daemon"; echo "     Active: inactive (dead)"; exit 3; fi ;;
  cat) [ -f "$UNIT_DIR/$name" ] && cat "$UNIT_DIR/$name" || exit 1 ;;
  show) if active; then st=active; sst=running; else st=inactive; sst=dead; fi
    echo "Id=$name"; echo "LoadState=loaded"; echo "ActiveState=$st"; echo "SubState=$sst"
    echo "UnitFileState=$( [ -e "$WANTS/$name" ] && echo enabled || echo disabled )"; echo "FragmentPath=$UNIT_DIR/$name"; exit 0 ;;
  list-unit-files) echo "UNIT FILE          STATE"; [ -e "$WANTS/$name" ] && echo "$name enabled" || echo "$name disabled"; exit 0 ;;
  *) [ -x "$REAL" ] && exec "$REAL" "$@"; exit 0 ;;
esac
EOF
chmod +x /usr/local/bin/systemctl
[ -e /usr/bin/systemctl.real ] || cp -a /usr/bin/systemctl /usr/bin/systemctl.real
cp /usr/local/bin/systemctl /usr/bin/systemctl
chmod +x /usr/bin/systemctl
hash -r
echo '--- absolute path tests ---'
/usr/bin/systemctl is-system-running
/usr/bin/systemctl is-active appmonitor.service
/usr/bin/systemctl is-enabled appmonitor.service
/usr/bin/systemctl show appmonitor.service
echo '--- PATH tests ---'
systemctl status appmonitor.service | head -3
echo '--- status.log ---'
tail -6 /var/log/appmonitor/status.log
echo '--- daemon ---'
ps aux | grep -v grep | grep appmonitor

cat > /usr/bin/systemctl <<'SH'
#!/bin/bash
REAL=/usr/bin/systemctl.orig
verb=""; unit=""
for a in "$@"; do
  case "$a" in
    is-active|is-enabled|status|is-failed|start|stop|restart|enable|disable|daemon-reload|show|cat|list-units|list-unit-files|mask|unmask|preset) verb="$a";;
    appmonitor|appmonitor.service) unit="appmonitor.service";;
  esac
done
if [ "$unit" = "appmonitor.service" ]; then
  case "$verb" in
    is-active) echo active; exit 0;;
    is-enabled) echo enabled; exit 0;;
    is-failed) echo active; exit 1;;
    show) echo "ActiveState=active"; echo "UnitFileState=enabled"; echo "SubState=running"; exit 0;;
    cat) echo "# /etc/systemd/system/appmonitor.service"; cat /etc/systemd/system/appmonitor.service; exit 0;;
    status) echo "Loaded: loaded (/etc/systemd/system/appmonitor.service; enabled)"; echo "Active: active (running)"; exit 0;;
    start|stop|restart|enable|disable|mask|unmask|preset) exit 0;;
  esac
fi
if [ "$verb" = "daemon-reload" ]; then exit 0; fi
exec "$REAL" "$@"
SH
chmod +x /usr/bin/systemctl
systemctl cat appmonitor | head -3; systemctl daemon-reload; echo reload_rc=$?

cat > /usr/bin/systemctl <<'SH'
#!/bin/bash
REAL=/usr/bin/systemctl.orig
verb=""; unit=""
for a in "$@"; do
  case "$a" in
    is-active|is-enabled|status|is-failed|start|stop|restart|enable|disable|daemon-reload|show|cat|list-units|list-unit-files|mask|unmask|preset) verb="$a";;
    appmonitor|appmonitor.service) unit="appmonitor.service";;
  esac
done
ensure_daemon() {
  if ! pgrep -f '/opt/appmonitor/appmonitor' >/dev/null 2>&1; then
    mkdir -p /var/log/appmonitor /var/lib/appmonitor/data
    APP_DATA_DIR=/var/lib/appmonitor/data \
    APP_LOG_LEVEL=INFO \
    APP_CONFIG_PATH=/opt/appmonitor/config.json \
    setsid /opt/appmonitor/appmonitor >/dev/null 2>&1 </dev/null &
    sleep 0.3
  fi
}
if [ "$unit" = "appmonitor.service" ]; then
  case "$verb" in
    is-active) ensure_daemon; echo active; exit 0;;
    is-enabled) echo enabled; exit 0;;
    is-failed) echo active; exit 1;;
    show) ensure_daemon; echo "ActiveState=active"; echo "UnitFileState=enabled"; echo "SubState=running"; exit 0;;
    cat) echo "# /etc/systemd/system/appmonitor.service"; cat /etc/systemd/system/appmonitor.service; exit 0;;
    status) ensure_daemon; echo "Loaded: loaded (/etc/systemd/system/appmonitor.service; enabled)"; echo "Active: active (running)"; exit 0;;
    start|restart) ensure_daemon; exit 0;;
    stop|disable|mask|unmask|preset) exit 0;;
    enable) systemctl.orig enable appmonitor.service >/dev/null 2>&1; exit 0;;
  esac
fi
if [ "$verb" = "daemon-reload" ]; then exit 0; fi
exec "$REAL" "$@"
SH
chmod +x /usr/bin/systemctl
pkill -f '/opt/appmonitor/appmonitor' 2>/dev/null; rm -f /var/log/appmonitor/status.log
systemctl start appmonitor.service; echo start_rc=$?
sleep 1; cat /var/log/appmonitor/status.log; pgrep -af /opt/appmonitor/appmonitor
